/**
 * body.ts — rigid bodies (dynamic AABBs and static AABBs).
 */

export interface Vec2 {
  x: number;
  y: number;
}

export function vec(x = 0, y = 0): Vec2 {
  return { x, y };
}

export interface BodyOptions {
  /** Center of the AABB in world space. */
  position?: Vec2;
  velocity?: Vec2;
  /** Half-width / half-height of the box. */
  halfExtents?: Vec2;
  /** Mass for dynamic bodies (ignored when isStatic). */
  mass?: number;
  isStatic?: boolean;
  friction?: number;
  restitution?: number;
}

export class Body {
  readonly position: Vec2;
  readonly velocity: Vec2;

  readonly halfExtents: Vec2;

  readonly mass: number;
  readonly invMass: number;
  readonly isStatic: boolean;

  friction: number;
  restitution: number;

  constructor(options: BodyOptions = {}) {
    this.position = vec(options.position?.x ?? 0, options.position?.y ?? 0);
    this.velocity = vec(options.velocity?.x ?? 0, options.velocity?.y ?? 0);
    this.halfExtents = vec(
      options.halfExtents?.x ?? 0.5,
      options.halfExtents?.y ?? 0.5,
    );

    this.isStatic = options.isStatic ?? false;
    const mass = options.mass ?? 1;
    if (!this.isStatic && !(mass > 0)) {
      throw new Error('Dynamic bodies need a positive mass');
    }
    this.mass = this.isStatic ? Infinity : mass;
    this.invMass = this.isStatic ? 0 : 1 / mass;

    this.friction = options.friction ?? 0.4;
    this.restitution = options.restitution ?? 0;
  }

  get top(): number {
    return this.position.y + this.halfExtents.y;
  }
  get bottom(): number {
    return this.position.y - this.halfExtents.y;
  }
  get left(): number {
    return this.position.x - this.halfExtents.x;
  }
  get right(): number {
    return this.position.x + this.halfExtents.x;
  }

  applyImpulse(jx: number, jy: number): void {
    this.velocity.x += this.invMass * jx;
    this.velocity.y += this.invMass * jy;
  }

  speed(): number {
    return Math.hypot(this.velocity.x, this.velocity.y);
  }
}

