/**
 * solver.ts — contact generation, sequential-impulse velocity solver,
 * and Baumgarte-style positional correction.
 */

import type { Body } from './body.js';

/** Tunables per spec. */
export const PERCENT = 0.8; // Baumgarte correction percentage
export const SLOP = 0.01; // allowed penetration (m)

/** Contact between two AABBs. Normal points from a to b. */
export interface Contact {
  a: Body;
  b: Body;
  normalX: number;
  normalY: number;
  penetration: number;
  // Accumulated impulses (for clamping across iterations).
  normalImpulse: number;
  tangentImpulse: number;
}

/**
 * Narrow phase for AABBs. Returns null when the boxes do not overlap.
 * The contact normal is the axis of minimum penetration.
 */
export function collide(a: Body, b: Body): Contact | null {
  const dx = b.position.x - a.position.x;
  const dy = b.position.y - a.position.y;

  const overlapX = a.halfExtents.x + b.halfExtents.x - Math.abs(dx);
  if (overlapX <= 0) return null;

  const overlapY = a.halfExtents.y + b.halfExtents.y - Math.abs(dy);
  if (overlapY <= 0) return null;

  if (overlapX < overlapY) {
    const sx = dx >= 0 ? 1 : -1;
    return {
      a,
      b,
      normalX: sx,
      normalY: 0,
      penetration: overlapX,
      normalImpulse: 0,
      tangentImpulse: 0,
    };
  } else {
    const sy = dy >= 0 ? 1 : -1;
    return {
      a,
      b,
      normalX: 0,
      normalY: sy,
      penetration: overlapY,
      normalImpulse: 0,
      tangentImpulse: 0,
    };
  }
}

/**
 * Sequential impulses over all contacts. `iterations` Gauss-Seidel sweeps.
 * Restitution is taken from the pair (max of both), friction likewise.
 */
export function solveVelocities(contacts: Contact[], iterations: number): void {
  for (let it = 0; it < iterations; it++) {
    for (const c of contacts) {
      const { a, b } = c;
      const invSum = a.invMass + b.invMass;
      if (invSum === 0) continue; // static-static

      const nx = c.normalX;
      const ny = c.normalY;

      // Relative velocity at the contact.
      const rvx = b.velocity.x - a.velocity.x;
      const rvy = b.velocity.y - a.velocity.y;

      // --- Normal impulse ---
      const vn = rvx * nx + rvy * ny;
      if (vn < 0) {
        const e = Math.max(a.restitution, b.restitution);
        let j = -(1 + e) * vn / invSum;
        // Clamp accumulated impulse to be non-negative.
        const newImpulse = Math.max(c.normalImpulse + j, 0);
        j = newImpulse - c.normalImpulse;
        c.normalImpulse = newImpulse;

        a.applyImpulse(-j * nx, -j * ny);
        b.applyImpulse(j * nx, j * ny);
      }

      // --- Friction impulse (Coulomb, clamped by mu * normalImpulse) ---
      const tx = -ny;
      const ty = nx;
      const rv2x = b.velocity.x - a.velocity.x;
      const rv2y = b.velocity.y - a.velocity.y;
      const vt = rv2x * tx + rv2y * ty;

      let jt = -vt / invSum;
      const mu = Math.sqrt(a.friction * b.friction);
      const maxFriction = mu * c.normalImpulse;
      const newTangent = Math.min(
        Math.max(c.tangentImpulse + jt, -maxFriction),
        maxFriction,
      );
      jt = newTangent - c.tangentImpulse;
      c.tangentImpulse = newTangent;

      a.applyImpulse(-jt * tx, -jt * ty);
      b.applyImpulse(jt * tx, jt * ty);
    }
  }
}

/**
 * Baumgarte-style positional correction: push overlapping bodies apart
 * along the contact normal by PERCENT of the penetration beyond SLOP,
 * split proportionally to inverse mass. Static bodies never move.
 */
export function positionalCorrection(contacts: Contact[]): void {
  for (const c of contacts) {
    const { a, b } = c;
    const invSum = a.invMass + b.invMass;
    if (invSum === 0) continue;

    const correction =
      (Math.max(c.penetration - SLOP, 0) / invSum) * PERCENT;

    const cx = correction * c.normalX;
    const cy = correction * c.normalY;
    a.position.x -= cx * a.invMass;
    a.position.y -= cy * a.invMass;
    b.position.x += cx * b.invMass;
    b.position.y += cy * b.invMass;
  }
}

