/**
 * world.ts — simulation container: gravity, integration, broad/narrow phase.
 */

import { Body, vec, type Vec2 } from './body.js';
import {
  collide,
  positionalCorrection,
  solveVelocities,
  type Contact,
} from './solver.js';

export interface WorldOptions {
  gravity?: Vec2;
  /** Solver iterations per step (default 8). */
  iterations?: number;
}

export class World {
  gravity: Vec2;
  readonly bodies: Body[] = [];
  readonly iterations: number;

  constructor(options: WorldOptions = {}) {
    this.gravity = options.gravity ? vec(options.gravity.x, options.gravity.y) : vec(0, -9.81);
    this.iterations = options.iterations ?? 8;
  }

  add<T extends Body>(body: T): T {
    this.bodies.push(body);
    return body;
  }

  /**
   * Advance the simulation by dt seconds:
   * integrate forces -> generate contacts -> solve velocities (8 iterations)
   * -> integrate positions -> Baumgarte positional correction.
   */
  step(dt: number): void {
    const { bodies, gravity } = this;

    // 1. Integrate external forces into velocities.
    for (const b of bodies) {
      if (b.invMass === 0) continue;
      b.velocity.x += gravity.x * dt;
      b.velocity.y += gravity.y * dt;
    }

    // 2. Broad + narrow phase (O(n^2) AABB pairs — fine for mini scale).
    const contacts: Contact[] = [];
    for (let i = 0; i < bodies.length; i++) {
      for (let j = i + 1; j < bodies.length; j++) {
        const c = collide(bodies[i]!, bodies[j]!);
        if (c !== null) contacts.push(c);
      }
    }

    // 3. Resolve velocities with sequential impulses.
    solveVelocities(contacts, this.iterations);

    // 4. Integrate positions.
    for (const b of bodies) {
      if (b.invMass === 0) continue;
      b.position.x += b.velocity.x * dt;
      b.position.y += b.velocity.y * dt;
    }

    // 5. Positional correction (Baumgarte percent 0.8, slop 0.01).
    positionalCorrection(contacts);
  }
}

