/**
 * Acceptance tests for the mini impulse engine.
 */
import { describe, expect, it } from 'vitest';
import { Body } from '../src/body.js';
import { World } from '../src/world.js';

const DT = 1 / 60;
const TICKS = 600;
const FLOOR_TOP = 0; // static floor: center y=-1, half height 1

function makeWorld(): World {
  const world = new World();
  world.add(
    new Body({
      position: { x: 0, y: -1 },
      halfExtents: { x: 50, y: 1 },
      isStatic: true,
      friction: 0.5,
    }),
  );
  return world;
}

function box(x: number, y: number): Body {
  return new Body({
    position: { x, y },
    halfExtents: { x: 0.5, y: 0.5 },
    mass: 1,
    friction: 0.4,
    restitution: 0,
  });
}

describe('mini impulse physics', () => {
  it('single dropped box comes to rest on the floor within 600 ticks, penetration < 0.02', () => {
    const world = makeWorld();
    const b = world.add(box(0, 5));

    // speed[t] is measured after tick t completes
    const speeds: number[] = [];
    for (let t = 0; t < TICKS; t++) {
      world.step(DT);
      speeds.push(b.speed());
    }

    // Find first tick from which the box stays at rest (< 0.01) for 60 ticks.
    let restTick = -1;
    for (let t = 0; t + 60 <= speeds.length; t++) {
      let stable = true;
      for (let k = t; k < t + 60; k++) {
        if ((speeds[k] ?? Infinity) >= 0.01) {
          stable = false;
          break;
        }
      }
      if (stable) {
        restTick = t;
        break;
      }
    }

    expect(restTick).toBeGreaterThanOrEqual(0);
    expect(restTick).toBeLessThan(TICKS);
    expect(b.speed()).toBeLessThan(0.01);

    const penetration = FLOOR_TOP - b.bottom;
    expect(penetration).toBeGreaterThanOrEqual(-1e-9); // not sunk through floor
    expect(penetration).toBeLessThan(0.02);

    // And it actually fell and landed roughly where physics says it should.
    expect(Math.abs(b.position.x)).toBeLessThan(1e-9);
  });

  it('stack of 3 boxes settles with each box resting within 0.05 of the one below', () => {
    const world = makeWorld();
    const bottom = world.add(box(0, 0.5));
    const middle = world.add(box(0, 1.5));
    const top = world.add(box(0, 2.5));

    for (let t = 0; t < TICKS; t++) world.step(DT);

    for (const b of [bottom, middle, top]) {
      expect(b.speed()).toBeLessThan(0.01);
    }

    // Separation between upper bottom face and lower top face.
    const gapMid = middle.bottom - bottom.top;
    const gapTop = top.bottom - middle.top;
    expect(Math.abs(gapMid)).toBeLessThan(0.05);
    expect(Math.abs(gapTop)).toBeLessThan(0.05);

    // Nothing drifted sideways or sank through the floor.
    for (const b of [bottom, middle, top]) {
      expect(Math.abs(b.position.x)).toBeLessThan(0.01);
      expect(b.bottom).toBeGreaterThanOrEqual(FLOOR_TOP - 0.02);
    }
  });

  it('ticks-to-rest is deterministic across two runs', () => {
    const run = () => {
      const world = makeWorld();
      const a = world.add(box(0, 5));
      const stack = [
        world.add(box(3, 0.5)),
        world.add(box(3, 1.5)),
        world.add(box(3, 2.5)),
      ];

      let restTick = -1;
      let allSlowFor = 0;
      for (let t = 0; t < TICKS; t++) {
        world.step(DT);
        const maxSpeed = Math.max(a.speed(), ...stack.map((b) => b.speed()));
        allSlowFor = maxSpeed < 0.01 ? allSlowFor + 1 : 0;
        if (restTick === -1 && allSlowFor >= 60) restTick = t - 59;
      }

      return {
        restTick,
        positions: [a, ...stack].map((b) => ({ x: b.position.x, y: b.position.y })),
        velocities: [a, ...stack].map((b) => ({ x: b.velocity.x, y: b.velocity.y })),
      };
    };

    const r1 = run();
    const r2 = run();

    expect(r2.restTick).toBe(r1.restTick);
    expect(r1.restTick).toBeGreaterThan(0);
    expect(r2.positions).toEqual(r1.positions);
    expect(r2.velocities).toEqual(r1.velocities);
  });
});

