// No early-out for separating contacts: the accumulated-impulse clamp
// below correctly reduces a too-large warm-started impulse.
const vn = rvx * nx + rvy * ny;
const e = Math.max(a.restitution, b.restitution);
let j = -(1 + e) * vn / invSum;
const newImpulse = Math.max(c.normalImpulse + j, 0);
j = newImpulse - c.normalImpulse;
c.normalImpulse = newImpulse;

if (j !== 0) {
  a.applyImpulse(-j * nx, -j * ny);
  b.applyImpulse(j * nx, j * ny);
}

